// Independent vault capacity. These are normal loot units already generated by
// existing game rules; the vault NEVER creates items, item IDs, XP or currency.
export const GAME3D_LOOT_BAG_CAPACITY = 200;
export const GAME3D_LOOT_STORAGE_CAPACITY = 400;
export const emptyStorage = () => ({ version:1, items:[] });
export function normalizeStorage(raw) {
  if (!raw || raw.version !== 1 || !Array.isArray(raw.items)) return emptyStorage();
  const unique = new Set();
  return { version:1,items:raw.items.filter(item => {
    if (!item || typeof item.dropId !== 'string' || !item.dropId ||
        item.dropId.length > 128 || unique.has(item.dropId) ||
        typeof item.id !== 'string' || !item.id) return false;
    unique.add(item.dropId);
    return true;
  }).slice(0,GAME3D_LOOT_STORAGE_CAPACITY) };
}
export function countBagItems(inventory) {
  return Object.values(inventory || {}).reduce((count, items) =>
    count + (Array.isArray(items) ? items.length : 0), 0);
}
export function planStoredDrop(current, item) {
  const vault = normalizeStorage(current);
  if (!item || typeof item.dropId !== 'string' || !item.dropId ||
      typeof item.id !== 'string' || !item.id) return {ok:false,reason:'INVALID_ITEM'};
  if (vault.items.some(existing => existing.dropId === item.dropId))
    return {ok:true,duplicate:true,next:vault};
  if (vault.items.length >= GAME3D_LOOT_STORAGE_CAPACITY)
    return {ok:false,reason:'STORAGE_FULL'};
  const next = {...vault,items:[...vault.items,item]};
  // CharacterVault limits a single character-save key to 400 kB. Stay below
  // that ceiling with headroom so a crowded vault never breaks cloud saves.
  if (JSON.stringify(next).length > 300000)
    return {ok:false,reason:'STORAGE_SIZE_LIMIT'};
  return {ok:true,duplicate:false,next};
}
